   383	    private void notifyUsersAndUpdateSaleStatus(Xdg64 order, Xbf54 payment) {
   384	        try {
   385	            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());
   386	
